class Item:
    created = 0

    def __init__(self, name, stock):
        self.name = name
        self.__stock = stock
        Item.created += 1

    def sell(self, n):
        if n > self.__stock:
            raise ValueError("재고 부족")
        self.__stock -= n

    def restock(self, n):
        self.__stock += n

    def get_stock(self):
        return self.__stock

